mapper.select:
SELECT COUNT(*) FROM content_audience
WHERE content_type = #{contentType} AND content_id = #{contentId}
  AND target_type = 'FAMILY' AND target_id = #{targetId}

mapper.delete:
DELETE FROM content_audience
WHERE source_circle_id = #{circleId}
AND target_id = #{targetId}

mapper.select:
SELECT DISTINCT owner_family_id FROM content_audience
WHERE source_circle_id = #{circleId}
AND target_id = #{targetId}
